(()=>{
 const media=matchMedia('(hover:hover) and (pointer:fine) and (prefers-reduced-motion:no-preference)');
 if(!media.matches)return;
 const pointer=document.createElement('div');pointer.className='sky-pointer';pointer.setAttribute('aria-hidden','true');
 pointer.innerHTML='<span class="sky-pointer__halo"></span><svg class="sky-pointer__plane sky-pointer__plane-shadow" viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="M16 2.2c1 0 1.7 1.3 2 2.6l1.2 8.2 8.3 6.1c.9.6 1.2 1.4 1.2 2.2v2.1l-10-3.2-.5 5.6 3.3 2.3v1.8L16 28l-5.5 1.9v-1.8l3.3-2.3-.5-5.6-10 3.2v-2.1c0-.8.3-1.6 1.2-2.2l8.3-6.1L14 4.8c.3-1.3 1-2.6 2-2.6Z" fill="currentColor"/><path d="M16 7v15" stroke="currentColor" stroke-opacity=".5" stroke-width=".6"/></svg><svg class="sky-pointer__plane sky-pointer__plane-body" viewBox="0 0 32 32" fill="none" aria-hidden="true"><defs><linearGradient id="pointer-hull" x1="4" y1="2" x2="26" y2="26" gradientUnits="userSpaceOnUse"><stop stop-color="#fffdf6"/><stop offset=".43" stop-color="#c7d3d2"/><stop offset=".8" stop-color="#728f92"/><stop offset="1" stop-color="#e3ebe7"/></linearGradient></defs><path d="M16 1.7c1.2 0 2 1.5 2.2 3l1.1 7.7 8.4 6.5c.8.6 1.2 1.2 1.2 2.1v2.1l-10.1-3.2-.5 5.4 3.2 2.5v1.8L16 28l-5.5 1.6v-1.8l3.2-2.5-.5-5.4-10.1 3.2V21c0-.9.4-1.5 1.2-2.1l8.4-6.5 1.1-7.7c.2-1.5 1-3 2.2-3Z" fill="url(#pointer-hull)" stroke="#2c4d50" stroke-width=".55"/><path d="M14 8.1 16 3.2l2 4.9-1.2 4.2h-1.6Z" fill="#20485a"/><path d="M16 13v11" stroke="#456a68" stroke-width=".65"/><path d="M7 19.3 13.3 17M25 19.3 18.7 17" stroke="#f7fcf3" stroke-width=".65"/></svg><span class="sky-pointer__text"></span><span class="sky-pointer__ripple"></span>';
 document.body.append(pointer);document.documentElement.classList.add('has-custom-cursor');
 let x=-100,y=-100,tx=-100,ty=-100,lastX=0,lastY=0,heading=0,raf=0;
 const text=pointer.querySelector('.sky-pointer__text');
 function animate(){x+=(tx-x)*.36;y+=(ty-y)*.36;pointer.style.transform=`translate3d(${x-20}px,${y-20}px,0)`;if(Math.abs(tx-x)+Math.abs(ty-y)>.2)raf=requestAnimationFrame(animate);else raf=0}
 function move(e){if(e.pointerType&&e.pointerType!=='mouse')return;tx=e.clientX;ty=e.clientY;const dx=tx-lastX,dy=ty-lastY;if(Math.hypot(dx,dy)>3){const next=Math.atan2(dy,dx)*180/Math.PI+90;heading+=((next-heading+540)%360-180)*.24;pointer.style.setProperty('--heading',heading+'deg');pointer.style.setProperty('--bank',Math.max(-28,Math.min(28,dx*.8))+'deg')}lastX=tx;lastY=ty;pointer.classList.add('is-visible');if(!raf)raf=requestAnimationFrame(animate);const action=e.target.closest('a,button,summary,[role="button"]');pointer.classList.toggle('is-action',!!action);pointer.classList.toggle('is-light',!e.target.closest('#home,.photo-banner,.planner-section'));text.textContent=action?.dataset.hero?'View '+action.querySelector('.card-name')?.textContent:action?.dataset.detail?'Explore':action?.closest('a,button,summary')?'Open':''}
 document.addEventListener('pointermove',move,{passive:true});document.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse')return;pointer.classList.add('is-press');pointer.classList.remove('is-rippling');void pointer.offsetWidth;pointer.classList.add('is-rippling')},{passive:true});document.addEventListener('pointerup',()=>pointer.classList.remove('is-press'),{passive:true});document.addEventListener('pointercancel',()=>pointer.classList.remove('is-press'),{passive:true});document.addEventListener('mouseout',e=>{if(!e.relatedTarget)pointer.classList.remove('is-visible')});window.addEventListener('blur',()=>pointer.classList.remove('is-visible'));media.addEventListener('change',()=>{document.documentElement.classList.toggle('has-custom-cursor',media.matches);pointer.hidden=!media.matches});
})();
